begin;
do $$ declare sid uuid; before_coins bigint; n integer; ids text[]; lesson text;
begin
 select id into sid from public.flashcard_students where deleted_at is null order by id limit 1;
 perform eddie_farm.lock_wallet(sid);
 select balance into before_coins from eddie_farm.wallets where student_id=sid;
 perform eddie_farm.award_trophy(sid,'test','test',24,50,false);
 if (select balance from eddie_farm.wallets where student_id=sid)<>before_coins then raise exception 'Below threshold paid'; end if;
 perform eddie_farm.award_trophy(sid,'test','test',25,50,false);
 perform eddie_farm.award_trophy(sid,'test','test',25,50,false);
 if (select balance from eddie_farm.wallets where student_id=sid)<>before_coins+20 then raise exception 'Bronze/retry failed'; end if;
 perform eddie_farm.award_trophy(sid,'test','test',40,50,false);
 if (select balance from eddie_farm.wallets where student_id=sid)<>before_coins+50 then raise exception 'Silver failed'; end if;
 perform eddie_farm.award_trophy(sid,'test','test',50,50,false);
 if (select balance from eddie_farm.wallets where student_id=sid)<>before_coins+50 then raise exception 'Incomplete attempt gold paid'; end if;
 perform eddie_farm.award_trophy(sid,'test','test',50,50,true);
 perform eddie_farm.award_trophy(sid,'test','test',0,50,false);
 perform eddie_farm.award_trophy(sid,'test','test',50,50,true);
 if (select balance from eddie_farm.wallets where student_id=sid)<>before_coins+100 then raise exception 'Gold/reset/retry failed'; end if;
 perform eddie_farm.award_trophy(sid,'test','direct-gold',50,50,true);
 if (select balance from eddie_farm.wallets where student_id=sid)<>before_coins+200 then raise exception 'Direct gold failed'; end if;
 select lesson_id,question_ids into lesson,ids from eddie_farm.trophy_catalogue where system_key='sentence-structure' order by lesson_id limit 1;
 perform eddie_farm.observe_trophy('sentence_structure_attempts',jsonb_build_object('student_id',sid,'lesson_id',lesson,'total_count',50,'correct_count',50,'status','completed','result',jsonb_build_object('correctIds',jsonb_build_array('unknown','unknown'))));
 if (select balance from eddie_farm.wallets where student_id=sid)<>before_coins+200 then raise exception 'Invalid IDs paid'; end if;
 if has_function_privilege('anon','eddie_farm.award_trophy(uuid,text,text,integer,integer,boolean)','EXECUTE') then raise exception 'Public credit access'; end if;
 if has_table_privilege('anon','eddie_farm.trophy_rewards','INSERT') then raise exception 'Public ledger access'; end if;
 begin perform eddie_farm.trophy_summary('00000000-0000-0000-0000-000000000000'); raise exception 'Invalid session accepted'; exception when insufficient_privilege then null; end;
end $$;
do $$ declare sid uuid; p integer; before_coins bigint;
begin
 select id into sid from public.flashcard_students where deleted_at is null order by id limit 1;
 select practice into p from listening_rewards.practices where question_count=40 and not exists(select 1 from listening_rewards.progress x where x.student_id=sid and x.practice=practices.practice) and not exists(select 1 from eddie_farm.trophy_rewards x where x.student_id=sid and x.system_key='ielts-listening' and x.lesson_id='ielts-listening-practice-'||practices.practice) order by practice limit 1;
 select balance into before_coins from eddie_farm.wallets where student_id=sid;
 insert into listening_rewards.progress(student_id,practice,question_number) select sid,p,n from generate_series(1,20) n;
 if (select balance from eddie_farm.wallets where student_id=sid)<>before_coins+20 then raise exception 'Listening bronze trigger'; end if;
 insert into listening_rewards.progress(student_id,practice,question_number) select sid,p,n from generate_series(21,32) n;
 if (select balance from eddie_farm.wallets where student_id=sid)<>before_coins+50 then raise exception 'Listening silver trigger'; end if;
 insert into listening_rewards.progress(student_id,practice,question_number) select sid,p,n from generate_series(33,40) n;
 if (select balance from eddie_farm.wallets where student_id=sid)<>before_coins+100 then raise exception 'Listening gold trigger'; end if;
 update listening_rewards.progress set completed_at=completed_at where student_id=sid and practice=p;
 if (select balance from eddie_farm.wallets where student_id=sid)<>before_coins+100 then raise exception 'Listening repeat trigger'; end if;
end $$;
rollback;
select 'PASS: thresholds, incremental rewards, duplicates, resets, direct gold, invalid IDs, private credits, invalid session and live listening triggers' result;
